}
import { useState } from 'react';
import { asString, useSearchParam } from '../../url/useSearchParam';

// Sign-in: a name, no password. The signed-in name lives in the URL (`user`), so it outlives a click.
export function SignIn() {
  const [, setUser] = useSearchParam('user', asString);
  const [name, setName] = useState('');
  return (
    <form
      data-testid="signin-form"
      onSubmit={(e) => {
        e.preventDefault();
        const trimmed = name.trim();
        if (trimmed !== '') setUser(trimmed);
      }}
    >
      <input data-testid="signin-name" value={name} onChange={(e) => setName(e.target.value)} placeholder="Your name" />
      <button type="submit" data-testid="signin-submit">Sign in</button>
    </form>
  );
}

export function CurrentUser() {
  const [user, setUser] = useSearchParam('user', asString);
  return (
    <p>
      Signed in as <span data-testid="current-user">{user}</span>{' '}
      <button type="button" data-testid="signout" onClick={() => setUser(undefined)}>Sign out</button>
    </p>
  );
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { sheetTodayKey, useSheetToday, type SheetToday as SheetTodayDto } from './useSheetToday';

// Shows the active sheet's today and changes it. A blank date resets it to the real date.
export function SheetToday() {
  const [sheet] = useSearchParam('sheet', asString);
  const [user] = useSearchParam('user', asString);
  const today = useSheetToday(sheet);
  const [date, setDate] = useState('');
  const queryClient = useQueryClient();
  const save = useMutation({
    mutationFn: (value: string) =>
      postJson<SheetTodayDto>(`/api/sheets/${encodeURIComponent(sheet)}/today`, { today: value, user }),
    onSuccess: (saved) => {
      queryClient.setQueryData(sheetTodayKey(saved.sheet), saved);
      // Everything on the sheet may depend on its date: re-read it all.
      void queryClient.invalidateQueries({ queryKey: ['sheet', saved.sheet] });
    },
  });
  return (
    <form
      data-testid="sheet-today-form"
      onSubmit={(e) => {
        e.preventDefault();
        save.mutate(date.trim());
      }}
    >
      Today: <span data-testid="sheet-today">{today ?? ''}</span>{' '}
      <input
        type="date"
        data-testid="sheet-today-input"
        value={date}
        onChange={(e) => {
          setDate(e.target.value);
          save.reset();
        }}
      />
      <button type="submit" data-testid="sheet-today-save">Set today</button>
      {save.isError && <span data-testid="sheet-error" role="alert"> Could not change today.</span>}
    </form>
  );
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

export type SheetToday = { sheet: string; today: string };

export const sheetTodayKey = (sheet: string) => ['sheet', sheet, 'today'] as const;

/** The sheet's today (YYYY-MM-DD). Every date decision and default date on screen reads this —
 *  never `new Date()`. Undefined while loading. */
export function useSheetToday(sheet: string): string | undefined {
  const { data } = useQuery({
    queryKey: sheetTodayKey(sheet),
    queryFn: () => getJson<SheetToday>(`/api/sheets/${encodeURIComponent(sheet)}/today`),
    enabled: sheet !== '',
  });
  return data?.today;
}
import { QueryClient } from '@tanstack/react-query';

// Server data is NEVER copied into component state. A feature reads it with useQuery under its own
// key (e.g. ['clients'] / ['project', id, 'notes']) and changes it with useMutation +
// invalidateQueries. Two features share data by sharing a KEY, never by a parent holding it.
// retry:false + no focus refetching keep the e2e runs deterministic.
export const queryClient = new QueryClient({
  defaultOptions: {
    queries: { retry: false, refetchOnWindowFocus: false },
    mutations: { retry: false },
  },
});
import { useNavigate, useSearch } from '@tanstack/react-router';

/**
 * Read and write ONE search-param key.
 *
 * State that outlives a click lives in the URL, not in a parent component — a filter, a sort, a
 * toggle, which row is selected. The control that owns a key is a self-contained file, and whoever
 * reads the key does so directly. Search params are an open namespace (declared once in
 * routes/__root.tsx), so a new key needs no schema change.
 *
 *     const [status, setStatus] = useSearchParam('status', asString);
 */
export function useSearchParam<T>(
  key: string,
  decode: (raw: unknown) => T,
): [T, (value: T | undefined) => void] {
  const search = useSearch({ strict: false }) as Record<string, unknown>;
  const navigate = useNavigate();

  const set = (value: T | undefined) => {
    void navigate({
      to: '.', // stay on the current route; only the search changes
      // Only the one key changes; every other param is left exactly as it was, so two controls
      // never clobber each other.
      search: (prev: Record<string, unknown>) => {
        const next = { ...prev };
        if (value === undefined || value === '') {
          delete next[key];
        } else {
          next[key] = value;
        }
        return next;
      },
      replace: true,
    });
  };

  return [decode(search[key]), set];
}

export const asString = (raw: unknown): string => (typeof raw === 'string' ? raw : '');
export const asNumber = (raw: unknown): number | undefined => {
  const n = Number(raw);
  return raw === undefined || raw === '' || Number.isNaN(n) ? undefined : n;
};
export const asFlag = (raw: unknown): boolean => raw === 'true' || raw === true;
import React from 'react';
import { createRoot } from 'react-dom/client';
import { RouterProvider, createRouter } from '@tanstack/react-router';
import { QueryClientProvider } from '@tanstack/react-query';
import { routeTree } from './routeTree.gen';
// Side-effect import: finds every features/**/*.slot.tsx and registers it. Must run before render.
import './slots/discover';
import { queryClient } from './query/queryClient';

// The app's wiring: the router (its tree is generated from routes/) and the query cache (its keys
// are an open namespace). Routes live under routes/; a feature's files live under features/.
const router = createRouter({ routeTree, context: { queryClient } });

declare module '@tanstack/react-router' {
  interface Register {
    router: typeof router;
  }
}

createRoot(document.getElementById('root')!).render(
  <React.StrictMode>
    <QueryClientProvider client={queryClient}>
      <RouterProvider router={router} />
    </QueryClientProvider>
  </React.StrictMode>,
);

